sys_script_client.script:
function onSubmit() {
	ScriptLoader.getScripts('CustomUtils.jsdbx', function() {

		var ticketCreatedMessage = 'custom_ticket_created';
		var ticketEscalationConfirm = 'custom_ticket_escalation_confirm';
		var ticketYouCanceled = 'custom_ticket_you_cancel';

		CustomUtils.i18nTranslate(
			[ticketCreatedMessage, ticketEscalationConfirm, ticketYouCanceled], 
			function(translations) {

				// Simple hint to prevent submit infinite loop
				if (g_form.isTriggered || g_form.getIntValue('priority') !== 1)
				{
					// If confirmed via button, show success and allow submit
					if (g_form.isTriggered)
						delete g_form.isTriggered;

					g_form.clearMessages();
					g_form.addSuccessMessage(translations[ticketCreatedMessage]);

					return true;
				}

				// Trigger the Modal for validation
				let gm = new GlideModal("glide_confirm_basic");

				gm.setTitle("Confirmation");
				gm.setPreference("title", translations[ticketEscalationConfirm]);

				// Action on Validation
				gm.setPreference("onPromptComplete", function() {
					g_form.isTriggered = true;

					let action = g_form.getActionName(); 
					g_form.submit(action);
				});

				// Action on Cancel
				gm.setPreference("onPromptCancel", function() {
					g_form.clearMessages();
					g_form.addModerateMessage(translations[ticketYouCanceled]);
				});

				gm.render();

			});
	});


    // BLOCK the initial submission
    return false;
}
